def main():
    if not os.path.exists(SRC): sys.exit('Run from the repo root: %s not found.' % SRC)
    s = open(SRC, encoding='utf-8').read()
    if 'romeojuliet' not in s: sys.exit('This is not the live src/game.src.html.')
    if 'PRECON ARENA (fix_precon_arena)' in s: sys.exit('Already applied. Nothing changed.')
    for need, why in (('fix_commander_evolve', 'fix_commander_evolve.py'), ("case 'searchact'", 'fix_precon_bookmarks.py')):
        if need not in s: sys.exit('Run %s first. Nothing changed.' % why)
    for label, a, _, n in EDITS:
        if s.count(a) != n: sys.exit('Anchor "%s" found %d times (need %d). Nothing changed.' % (label, s.count(a), n))
    for _, a, b, _ in EDITS: s = s.replace(a, b)
    shutil.copy2(SRC, SRC + '.bak')
    open(SRC, 'w', encoding='utf-8').write(s)
    print('fix_precon_arena: PreCon Arena installed (Drawn Mode retired). Backup: %s.bak' % SRC)
if __name__ == '__main__': main()
